<script setup lang="ts">
import { stringify } from 'yaml'
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { getHyperparameterTemplate, type HyperparameterTemplate } from '../api/hyperparameters'
import PageHeader from '../components/PageHeader.vue'
const route=useRoute();const item=ref<HyperparameterTemplate>();const error=ref('');const raw=computed(()=>item.value?stringify(item.value.effective_parameters,{lineWidth:0}):'');onMounted(async()=>{try{item.value=await getHyperparameterTemplate(String(route.params.id))}catch(reason){error.value=reason instanceof Error?reason.message:'模板详情加载失败'}})
</script>
<template><main class="content-page detail-page"><PageHeader :title="item?.name||'模板详情'" back-to="/hyperparameter-templates" back-label="返回超参数模板"><template v-if="item?.system_key" #meta><el-tag effect="plain">系统模板</el-tag></template><template #actions><router-link v-if="item" :to="`/hyperparameter-templates/new?from=${item.id}`"><el-button type="primary">派生模板</el-button></router-link></template></PageHeader><div class="content-body"><el-alert v-if="error" :title="error" type="error" :closable="false"/><section v-if="item" class="detail-grid"><div><span>epochs</span><strong>{{ item.epochs }}</strong></div><div><span>batch size</span><strong>{{ item.batch_mode==='auto'?'auto':item.batch_value }}</strong></div><div><span>image size</span><strong>{{ item.image_size }}</strong></div><div><span>目录版本</span><code>{{ item.catalog_version }}</code></div><article><span>描述</span><p>{{ item.description||'暂无描述' }}</p></article><article><span>RAW 配置</span><pre>{{ raw }}</pre></article></section></div></main></template>
